window.docContents[149].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Inversion-Lemmas-for-Subtyping":{"contents":"Before we look at the properties of the typing relation, we need\nto establish a couple of critical structural properties of the\nsubtype relation:\n\n* Bool is the only subtype of Bool, and* every subtype of an arrow type is itself an arrow type.\n\n\n\nFormally:\n\ntheorem sub_inversion_bool (τ : Ty)\n    (h : τ <: <{ Bool }>) :\n    τ = Ty.bool := by\n  sorry\n\n\ntheorem sub_inversion_arrow {σ τ₁ τ₂ : Ty}\n     (h : σ <: <{ ~τ₁ → ~τ₂ }>) :\n     ∃ σ₁ σ₂,\n     σ = <{ ~σ₁ → ~σ₂ }> ∧ τ₁ <: σ₁ ∧ σ₂ <: τ₂ := by\n  sorry\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Properties","header":"8.3.1. Inversion Lemmas for Subtyping","id":"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Inversion-Lemmas-for-Subtyping"}});